(1308251, 168055, 24454, '<td valign="top">Tee Hee. . . THIS is awesome!!!   Perfect fit for the challenge, technically perfect, AND it''s just so creative and interesting.   10</td>', 'Tee Hee. . . THIS is awesome!!!   Perfect fit for the challenge, technically perfect, AND it''s just so creative and interesting.   10', '2005-04-20 14:49:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1308253, 168395, 35751, '<td valign="top">I think this is a good photo, a unique idea.</td>', 'I think this is a good photo, a unique idea.', '2005-04-20 14:50:11.000000', NULL, 1),
(1308256, 168486, 24454, '<td valign="top">This is one where the border makes it!   I love the way the red brings out the whole picture.  Good job!</td>', 'This is one where the border makes it!   I love the way the red brings out the whole picture.  Good job!', '2005-04-20 14:51:21.000000', NULL, 1),
(1308266, 168125, 24454, '<td valign="top">Wow!!!   Definitely the most beautiful picture I''ve seen so far in this challenge!   And it fits the challenge perfectly in the MOST interesting of ways.   I think we might see this one in the winner''s circle  :)    I hope so!    10</td>', 'Wow!!!   Definitely the most beautiful picture I''ve seen so far in this challenge!   And it fits the challenge perfectly in the MOST interesting of ways.   I think we might see this one in the winner''s circle  :)    I hope so!    10', '2005-04-20 14:56:51.000000', NULL, 1),
(1308267, 167423, 35804, '<td valign="top">One of my favorite pictures...I love the change in texture/clarity moving from left to right, beautiful soft light too.</td>', 'One of my favorite pictures...I love the change in texture/clarity moving from left to right, beautiful soft light too.', '2005-04-20 14:57:01.000000', NULL, 1),
(1308268, 167245, 24454, '<td valign="top">Nice!</td>', 'Nice!', '2005-04-20 14:57:04.000000', NULL, 1),
(1308269, 168579, 24454, '<td valign="top">Very cool!</td>', 'Very cool!', '2005-04-20 14:57:18.000000', NULL, 1),
(1308270, 168683, 35804, '<td valign="top">Pretty light, I''m really drawn to the shadows, very nicely done. one of my favorites.</td>', 'Pretty light, I''m really drawn to the shadows, very nicely done. one of my favorites.', '2005-04-20 14:57:25.000000', NULL, 1),
(1308272, 168629, 24454, '<td valign="top">REALLY beautiful!</td>', 'REALLY beautiful!', '2005-04-20 14:57:59.000000', NULL, 1),
(1308274, 168652, 35645, '<td valign="top">Out of focus and over saturated.</td>', 'Out of focus and over saturated.', '2005-04-20 14:58:33.000000', NULL, 1),
(1308279, 167200, 33893, '<td valign="top">This is a really cool shot, nice light, good colors, just seems a bit fuzzy... if you don''t have a tripod, you can always use your camera strap wrapped around your elbow to steady your camera.</td>', 'This is a really cool shot, nice light, good colors, just seems a bit fuzzy... if you don''t have a tripod, you can always use your camera strap wrapped around your elbow to steady your camera.', '2005-04-20 14:59:08.000000', NULL, 1),
(1308281, 167612, 24454, '<td valign="top">AWESOME!!!   This is the 2nd one I''ve seen that makes you immediately think:  RIBBON!!  Good Luck!!!  10</td>', 'AWESOME!!!   This is the 2nd one I''ve seen that makes you immediately think:  RIBBON!!  Good Luck!!!  10', '2005-04-20 14:59:23.000000', NULL, 1),
(1308284, 167884, 35645, '<td valign="top">Out of focus (I know it''s motion blur on the hands). I can''t really tell what it is I''m supposed to be looking at. Where is the focal point of the composition?</td>', 'Out of focus (I know it''s motion blur on the hands). I can''t really tell what it is I''m supposed to be looking at. Where is the focal point of the composition?', '2005-04-20 14:59:53.000000', NULL, 1),
(1308290, 167170, 35645, '<td valign="top">Interesting and creative concept. Composition is ok. Focus is ok. Lighting is intense (not bad, just intense) and does a good job of conveying ''rock star''.</td>', 'Interesting and creative concept. Composition is ok. Focus is ok. Lighting is intense (not bad, just intense) and does a good job of conveying ''rock star''.', '2005-04-20 15:01:33.000000', NULL, 1),
(1308300, 168126, 35645, '<td valign="top">I don''t know if it''s a result of the glare from the lighting, or a focusing issue, but the whole image is just a hair out of focus - enough to be noticed, not enough to convey ''intentional soft focus''. Also, you may wish to try toning down the red saturation.</td>', 'I don''t know if it''s a result of the glare from the lighting, or a focusing issue, but the whole image is just a hair out of focus - enough to be noticed, not enough to convey ''intentional soft focus''. Also, you may wish to try toning down the red saturation.', '2005-04-20 15:03:57.000000', NULL, 1),
(1308307, 167880, 35645, '<td valign="top">Nice pic of a railway bridge, but not enough emphasis on the rocks in my view to qualify as meeting the challenge. Love the perspective and lines, nice DOF, good choice of B&amp;W for your subject.</td>', 'Nice pic of a railway bridge, but not enough emphasis on the rocks in my view to qualify as meeting the challenge. Love the perspective and lines, nice DOF, good choice of B&W for your subject.', '2005-04-20 15:06:14.000000', NULL, 1),
(1308312, 168436, 35645, '<td valign="top">Gorgeous macro. Beautiful clarity. Interesting concept. Great texture. Good lighting.</td>', 'Gorgeous macro. Beautiful clarity. Interesting concept. Great texture. Good lighting.', '2005-04-20 15:07:38.000000', NULL, 1),
(1308314, 168125, 35645, '<td valign="top">Beautiful colors. Great composition. Where is this?</td>', 'Beautiful colors. Great composition. Where is this?', '2005-04-20 15:08:19.000000', NULL, 1),
(1308319, 167288, 33893, '<td valign="top">Love this angle and the lighting!</td>', 'Love this angle and the lighting!', '2005-04-20 15:09:37.000000', NULL, 1),
(1308328, 167880, 33893, '<td valign="top">Maybe you should have clarified this shot''s connection with the challenge topic.</td>', 'Maybe you should have clarified this shot''s connection with the challenge topic.', '2005-04-20 15:12:30.000000', NULL, 1),
(1308335, 168697, 33893, '<td valign="top">Very creative, nice lighting... well done!</td>', 'Very creative, nice lighting... well done!', '2005-04-20 15:13:23.000000', NULL, 1),
(1308337, 168488, 33893, '<td valign="top">Didn''t know we had a jewelry shot coming up did ya? Well, this was good practice! Well done, but I might have tried the paper between ring and scissors for a little more definition of the ring.</td>', 'Didn''t know we had a jewelry shot coming up did ya? Well, this was good practice! Well done, but I might have tried the paper between ring and scissors for a little more definition of the ring.', '2005-04-20 15:14:42.000000', NULL, 1),
(1308345, 168703, 35229, '<td valign="top">To bright. Good idea.</td>', 'To bright. Good idea.', '2005-04-20 15:17:10.000000', NULL, 1),
(1308354, 168414, 9295, '<td valign="top">I love the picture but it''s really stretching the challenge theme, especially with the rock in the soft background.  Great picture though, so I''m going to give you the benefit of the doubt and vote you higher than I might otherwise have given it.</td>', 'I love the picture but it''s really stretching the challenge theme, especially with the rock in the soft background.  Great picture though, so I''m going to give you the benefit of the doubt and vote you higher than I might otherwise have given it.', '2005-04-20 15:19:17.000000', NULL, 1),
(1308379, 168125, 12045, '<td valign="top">Really nice shot. 10</td>', 'Really nice shot. 10', '2005-04-20 15:25:05.000000', NULL, 1),
(1308386, 168545, 33947, '<td valign="top">Fun composition. Nice and sharp. Like the title.</td>', 'Fun composition. Nice and sharp. Like the title.', '2005-04-20 15:26:34.000000', NULL, 1),
(1308392, 167200, 33947, '<td valign="top">I like the different shades of moss on the stones in contrast with the gray ones...interesting.  Wish they were a bit sharper, though.</td>', 'I like the different shades of moss on the stones in contrast with the gray ones...interesting.  Wish they were a bit sharper, though.', '2005-04-20 15:31:36.000000', NULL, 1),
(1308395, 167378, 33947, '<td valign="top">Great idea! Like the tight cropping. Lighting is a bit flat, but still, I enjoy this photo.</td>', 'Great idea! Like the tight cropping. Lighting is a bit flat, but still, I enjoy this photo.', '2005-04-20 15:34:16.000000', NULL, 1),
(1308410, 168671, 33947, '<td valign="top">I like the nice, simple composition, but, since the rock is the main part of the picture that makes the photo fit the challenge, I wish it were more distinct and in better focus.</td>', 'I like the nice, simple composition, but, since the rock is the main part of the picture that makes the photo fit the challenge, I wish it were more distinct and in better focus.', '2005-04-20 15:41:06.000000', NULL, 1),
(1308412, 168399, 6814, '<td valign="top">If the colors were more vibrant, this might be a more interesting image.  To me, this is dull and lifeless.</td>', 'If the colors were more vibrant, this might be a more interesting image.  To me, this is dull and lifeless.', '2005-04-20 15:41:28.000000', NULL, 1),
(1308426, 166242, 6814, '<td valign="top">I love the reflection in the water.  A little more saturation would help this shot.</td>', 'I love the reflection in the water.  A little more saturation would help this shot.', '2005-04-20 15:45:00.000000', NULL, 1),
(1308430, 168297, 24413, '<td valign="top">Very creative!</td>', 'Very creative!', '2005-04-20 15:46:24.000000', NULL, 1),
(1308432, 166774, 6814, '<td valign="top">Beautiful color.  The only weakness is that the horizon is not quite straight.</td>', 'Beautiful color.  The only weakness is that the horizon is not quite straight.', '2005-04-20 15:46:32.000000', NULL, 1),
(1308436, 168571, 33736, '<td valign="top">Wish crisper were more possible, but this is terrific.  9</td>', 'Wish crisper were more possible, but this is terrific.  9', '2005-04-20 15:47:46.000000', NULL, 1),
(1308440, 168414, 33947, '<td valign="top">Great snake and captivating picture! My only concern is that since the rock is the element that makes the photo qualify for this challenge, I wish it played a more prominent role. That said, I still enjoy the photo. Good lighting and cropping. I love the detail on the head.</td>', 'Great snake and captivating picture! My only concern is that since the rock is the element that makes the photo qualify for this challenge, I wish it played a more prominent role. That said, I still enjoy the photo. Good lighting and cropping. I love the detail on the head.', '2005-04-20 15:48:05.000000', NULL, 1),
(1308441, 168413, 6814, '<td valign="top">Very nice image.  I like the sharpness of the image and the use of natural light.</td>', 'Very nice image.  I like the sharpness of the image and the use of natural light.', '2005-04-20 15:48:11.000000', NULL, 1),
(1308443, 168152, 33736, '<td valign="top">A super-heroic job!   10</td>', 'A super-heroic job!   10', '2005-04-20 15:48:37.000000', NULL, 1),
(1308450, 168002, 33947, '<td valign="top">I''m sorry, I can''t tell what this is. From a strict composition point of view it has a nice flow in the curves, but the blurriness is a distraction.</td>', 'I''m sorry, I can''t tell what this is. From a strict composition point of view it has a nice flow in the curves, but the blurriness is a distraction.', '2005-04-20 15:51:52.000000', NULL, 1),
(1308462, 166915, 33736, '<td valign="top">Funny. First I thought you over processed the silver scissors. By the time the pic finished downloading, it was clear what you did.  The rocks are terrific, but you might have chosen a different color paper (light yellow or cream to compliment the lighter parts of the rocks.)  7</td>', 'Funny. First I thought you over processed the silver scissors. By the time the pic finished downloading, it was clear what you did.  The rocks are terrific, but you might have chosen a different color paper (light yellow or cream to compliment the lighter parts of the rocks.)  7', '2005-04-20 15:55:42.000000', NULL, 1),
(1308466, 167185, 34134, '<td valign="top">Focus is a bit soft on the foreground. Interesting angle.</td>', 'Focus is a bit soft on the foreground. Interesting angle.', '2005-04-20 15:56:30.000000', NULL, 1),
(1308468, 168297, 33947, '<td valign="top">Major points for coming up with a fun concept, however, the jumble of black handles in the mirror hurts the composition, and the gray cloth is a distraction. You gotta love the skirts, though!!!</td>', 'Major points for coming up with a fun concept, however, the jumble of black handles in the mirror hurts the composition, and the gray cloth is a distraction. You gotta love the skirts, though!!!', '2005-04-20 15:56:55.000000', NULL, 1),
(1308472, 168399, 34134, '<td valign="top">Colors are very muddy and detract from quality of this image. Focus too soft.<br/></td>', 'Colors are very muddy and detract from quality of this image. Focus too soft.', '2005-04-20 15:57:25.000000', NULL, 1),
(1308474, 167163, 21786, '<td valign="top">oh! really so funny I like your concept!</td>', 'oh! really so funny I like your concept!', '2005-04-20 15:57:32.000000', NULL, 1),
(1308480, 168635, 34134, '<td valign="top">Like the effect.</td>', 'Like the effect.', '2005-04-20 16:00:24.000000', NULL, 1),
(1308483, 168571, 33947, '<td valign="top">Great concept!  I did it, too. : ) Seriously, I love the glowing effect from the back lighting. Works great.</td>', 'Great concept!  I did it, too. : ) Seriously, I love the glowing effect from the back lighting. Works great.', '2005-04-20 16:01:30.000000', NULL, 1),
(1308485, 167880, 34134, '<td valign="top">Interesting perspective. More contrast would make this a super picture. Doesn''t meet the  challange, though. (Maybe it''s the Rock Island Line?)</td>', 'Interesting perspective. More contrast would make this a super picture. Doesn''t meet the  challange, though. (Maybe it''s the Rock Island Line?)', '2005-04-20 16:03:06.000000', NULL, 1),
(1308491, 168485, 34134, '<td valign="top">More contrast would really help this picture. Also, the DOF should be increased.... the front of the sissors is not in focus.</td>', 'More contrast would really help this picture. Also, the DOF should be increased.... the front of the sissors is not in focus.', '2005-04-20 16:05:49.000000', NULL, 1),
(1308494, 167423, 35827, '<td valign="top">nice! I like the dramatic effects on this.</td>', 'nice! I like the dramatic effects on this.', '2005-04-20 16:06:47.000000', NULL, 1),
(1308497, 167010, 34134, '<td valign="top">Picture needs to be tilted about 2 degrees CCW. Very distracting.</td>', 'Picture needs to be tilted about 2 degrees CCW. Very distracting.', '2005-04-20 16:07:19.000000', NULL, 1),
(1308501, 168436, 33947, '<td valign="top">Very good lighting. It''s a little hard to get oriented, though, and appreciate the scissors for what they are. Visually confusing. Paper is nice and sharp.</td>', 'Very good lighting. It''s a little hard to get oriented, though, and appreciate the scissors for what they are. Visually confusing. Paper is nice and sharp.', '2005-04-20 16:08:19.000000', NULL, 1),
(1308509, 167207, 29906, '<td valign="top">Very creative, exposure is not bad too, I gave it a 10 just for the creativity</td>', 'Very creative, exposure is not bad too, I gave it a 10 just for the creativity', '2005-04-20 16:10:52.000000', NULL, 1),
(1308511, 168055, 29906, '<td valign="top">Nice shot - 8</td>', 'Nice shot - 8', '2005-04-20 16:11:34.000000', NULL, 1),
(1308521, 167098, 34134, '<td valign="top">Photo really suffers from soft focus. Was this on a tripod?</td>', 'Photo really suffers from soft focus. Was this on a tripod?', '2005-04-20 16:16:10.000000', NULL, 1),
(1308522, 168710, 33947, '<td valign="top">Creative approach. Wish they were lit better.</td>', 'Creative approach. Wish they were lit better.', '2005-04-20 16:16:14.000000', NULL, 1),
(1308526, 167762, 24454, '<td valign="top">Absolutely GORGEOUS!!!!   Has to be one of the top 3.   Just has to be!!   10</td>', 'Absolutely GORGEOUS!!!!   Has to be one of the top 3.   Just has to be!!   10', '2005-04-20 16:17:50.000000', NULL, 1),
(1308529, 168410, 33947, '<td valign="top">Fun idea...the hair is great.  I wish it were sharper, though.</td>', 'Fun idea...the hair is great.  I wish it were sharper, though.', '2005-04-20 16:18:27.000000', NULL, 1),
