(1308531, 168447, 24454, '<td valign="top">I love this one.   The colors are vivid.   The focus and depth of field are so amazing.  It almost looks 3-dimensional.   The composition is interesting.   EXCELLENT job!!!  10</td>', 'I love this one.   The colors are vivid.   The focus and depth of field are so amazing.  It almost looks 3-dimensional.   The composition is interesting.   EXCELLENT job!!!  10', '2005-04-20 16:20:55.000000', NULL, 1),
(1308534, 167624, 34134, '<td valign="top">The background is very distracting.</td>', 'The background is very distracting.', '2005-04-20 16:21:24.000000', NULL, 1),
(1308535, 167956, 24454, '<td valign="top">Great composition!   This is reallyl nice to look at.   Not dry and boring like some.</td>', 'Great composition!   This is reallyl nice to look at.   Not dry and boring like some.', '2005-04-20 16:21:46.000000', NULL, 1),
(1308536, 167163, 33947, '<td valign="top">Beautiful lighting on water and in background. I''ve grown pretty tired of toilet paper as a subject, but I must say, in this instance it works! Fun idea.</td>', 'Beautiful lighting on water and in background. I''ve grown pretty tired of toilet paper as a subject, but I must say, in this instance it works! Fun idea.', '2005-04-20 16:22:31.000000', NULL, 1),
(1308537, 166699, 24454, '<td valign="top">Very pretty!!!</td>', 'Very pretty!!!', '2005-04-20 16:22:36.000000', NULL, 1),
(1308539, 168486, 34134, '<td valign="top">Creative. I like they way the border mirrors the handles, but don''t think I like the border. Technically nice.</td>', 'Creative. I like they way the border mirrors the handles, but don''t think I like the border. Technically nice.', '2005-04-20 16:23:11.000000', NULL, 1),
(1308542, 168703, 34134, '<td valign="top">Clever idea, but the focus is too soft and the print too light to really enjoy.</td>', 'Clever idea, but the focus is too soft and the print too light to really enjoy.', '2005-04-20 16:24:29.000000', NULL, 1),
(1308543, 167208, 33947, '<td valign="top">Your big red rock is gorgeous. Good composition. Well cropped.</td>', 'Your big red rock is gorgeous. Good composition. Well cropped.', '2005-04-20 16:24:31.000000', NULL, 1),
(1308548, 168512, 33947, '<td valign="top">Like your point of view, but this needs to be sharper.</td>', 'Like your point of view, but this needs to be sharper.', '2005-04-20 16:25:57.000000', NULL, 1),
