(1308553, 168173, 33947, '<td valign="top">Lovely composition. Just enough of the scissors to make it interesting. Like the blurred background.</td>', 'Lovely composition. Just enough of the scissors to make it interesting. Like the blurred background.', '2005-04-20 16:27:11.000000', NULL, 1),
(1308555, 167200, 34134, '<td valign="top">Photo is way out of focus. I don''t think this is from resizing. The horizon needs to be leveled-- very distracting.</td>', 'Photo is way out of focus. I don''t think this is from resizing. The horizon needs to be leveled-- very distracting.', '2005-04-20 16:27:56.000000', NULL, 1),
(1308560, 168297, 15575, '<td valign="top">HAHAHA...what a great idea!!  And the sissors look very fetching in those dresses! ;-)</td>', 'HAHAHA...what a great idea!!  And the sissors look very fetching in those dresses! ;-)', '2005-04-20 16:29:21.000000', NULL, 1),
(1308562, 166337, 33947, '<td valign="top">Creative and interesting compositiion. Like the simplicity of it...subject and color wise.</td>', 'Creative and interesting compositiion. Like the simplicity of it...subject and color wise.', '2005-04-20 16:30:12.000000', NULL, 1),
(1308563, 167369, 24454, '<td valign="top">Awwwww. . . .I love it that you have the little pup in the picture!!!!   He just makes it!!   I''m finding that in general, it''s kind of a boring subject, but put that cute little dog in it and all of a sudden, it speaks to me  :)    10</td>', 'Awwwww. . . .I love it that you have the little pup in the picture!!!!   He just makes it!!   I''m finding that in general, it''s kind of a boring subject, but put that cute little dog in it and all of a sudden, it speaks to me  :)    10', '2005-04-20 16:30:13.000000', NULL, 1),
(1308565, 167208, 24454, '<td valign="top">A Wow Picture!!!!!!!!!!   Beautiful!!</td>', 'A Wow Picture!!!!!!!!!!   Beautiful!!', '2005-04-20 16:30:40.000000', NULL, 1),
(1308568, 166682, 24454, '<td valign="top">Nice way to enhance rocks!!!    This is beautiful!</td>', 'Nice way to enhance rocks!!!    This is beautiful!', '2005-04-20 16:32:20.000000', NULL, 1),
(1308570, 168416, 24454, '<td valign="top">VERY nice!!!!!</td>', 'VERY nice!!!!!', '2005-04-20 16:33:20.000000', NULL, 1),
(1308572, 168052, 33947, '<td valign="top">Like the title, and like the choice of paper...works nicely with the gravel and cactus and black-handled scissors. Good eye.</td>', 'Like the title, and like the choice of paper...works nicely with the gravel and cactus and black-handled scissors. Good eye.', '2005-04-20 16:34:19.000000', NULL, 1),
(1308573, 168598, 35827, '<td valign="top">i find the darkened top corners a little distracting.</td>', 'i find the darkened top corners a little distracting.', '2005-04-20 16:34:21.000000', NULL, 1),
