(1308583, 167898, 33947, '<td valign="top">VERY NEAT EGG! Like the simplicity of the shot. Nice lighting.</td>', 'VERY NEAT EGG! Like the simplicity of the shot. Nice lighting.', '2005-04-20 16:36:12.000000', NULL, 1),
