(1309195, 168684, 31211, '<td valign="top">Nice title and shot.  I think its is a little too bright and could use a little more contrast, perhaps. Anyway, how did you manage to display the scissors like that? did you glue them or something? lol<br/>Good job, hope you do well on this challenge.</td>', 'Nice title and shot.  I think its is a little too bright and could use a little more contrast, perhaps. Anyway, how did you manage to display the scissors like that? did you glue them or something? lolGood job, hope you do well on this challenge.', '2005-04-20 20:39:51.000000', NULL, 1),
(1309199, 168449, 31211, '<td valign="top">I''m not sure about the composition, but the colors on the rocks and the image''s definition are absolutely perfect. Great shot.</td>', 'I''m not sure about the composition, but the colors on the rocks and the image''s definition are absolutely perfect. Great shot.', '2005-04-20 20:41:55.000000', NULL, 1),
(1309206, 167612, 31211, '<td valign="top">Amazing shot. Great quality and definition, great colors and light. The water came out very nice, so did the sky. 9</td>', 'Amazing shot. Great quality and definition, great colors and light. The water came out very nice, so did the sky. 9', '2005-04-20 20:44:20.000000', NULL, 1),
(1309214, 168140, 31211, '<td valign="top">lol<br/>Gave you a 7 for creativity and effort. Although it is a clever and funny image, the scissors are out of focus and lack a bit of contrast.<br/>Anyway, good job.</td>', 'lolGave you a 7 for creativity and effort. Although it is a clever and funny image, the scissors are out of focus and lack a bit of contrast.Anyway, good job.', '2005-04-20 20:48:37.000000', NULL, 1),
(1309221, 168377, 31211, '<td valign="top">Very nice catch. Like this picture very much, but I cant help noticing the person reading the paper is out fo focus. Anyway, good composition and nice approach of the challenge. Well done.</td>', 'Very nice catch. Like this picture very much, but I cant help noticing the person reading the paper is out fo focus. Anyway, good composition and nice approach of the challenge. Well done.', '2005-04-20 20:50:56.000000', NULL, 1),
(1309223, 168396, 36671, '<td valign="top">I thought this was a great idea that incorporated all the aspects of the challenge very nice.</td>', 'I thought this was a great idea that incorporated all the aspects of the challenge very nice.', '2005-04-20 20:53:30.000000', NULL, 1),
(1309224, 168628, 14369, '<td valign="top">little too out of focus for me</td>', 'little too out of focus for me', '2005-04-20 20:53:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1309226, 167475, 36671, '<td valign="top">It is a good idea however the photo of the rock is excessively grainy and there is too much light coming from the scissors, good job at utilizing all aspects of the challenge though.</td>', 'It is a good idea however the photo of the rock is excessively grainy and there is too much light coming from the scissors, good job at utilizing all aspects of the challenge though.', '2005-04-20 20:55:03.000000', NULL, 1),
(1309227, 167776, 36671, '<td valign="top">This was a good idea but I feel that maybe a different lighting could have made the colors stand out or pop a bit more ... the crystal rock is good but so many scissors, large sheet of paper but only one rock. Good job though.</td>', 'This was a good idea but I feel that maybe a different lighting could have made the colors stand out or pop a bit more ... the crystal rock is good but so many scissors, large sheet of paper but only one rock. Good job though.', '2005-04-20 20:57:05.000000', NULL, 1),
(1309228, 167875, 36671, '<td valign="top">hmm... scissors and paper? nice rock structure though.</td>', 'hmm... scissors and paper? nice rock structure though.', '2005-04-20 20:57:43.000000', NULL, 1),
(1309237, 167970, 36671, '<td valign="top">nice technical aspect to rock scissors paper my personal opinion would have been to use a gray or a bluish tint to the back ground rather than the diffused somewhat yellowish tint that I see. HOWEVER it is a good picture and a great idea.</td>', 'nice technical aspect to rock scissors paper my personal opinion would have been to use a gray or a bluish tint to the back ground rather than the diffused somewhat yellowish tint that I see. HOWEVER it is a good picture and a great idea.', '2005-04-20 20:59:55.000000', NULL, 1),
