(1311036, 168684, 34243, '<td valign="top">Interesting concept and choice of colours.</td>', 'Interesting concept and choice of colours.', '2005-04-21 13:53:42.000000', NULL, 1),
(1311164, 168445, 35513, '<td valign="top">I LOVE these scissors!!!  If you know where they were found, I would REALLY like to pick up a pair!  I also really like this shot.  There''s beautiful contrast between the whites/lights and the dark colors of the stones and fabric.  Well done.</td>', 'I LOVE these scissors!!!  If you know where they were found, I would REALLY like to pick up a pair!  I also really like this shot.  There''s beautiful contrast between the whites/lights and the dark colors of the stones and fabric.  Well done.', '2005-04-21 14:58:41.000000', NULL, 1),
(1311167, 168487, 35513, '<td valign="top">Not a bad concept for the photo, but it''s a little bit blurry, making the hands indistinct.</td>', 'Not a bad concept for the photo, but it''s a little bit blurry, making the hands indistinct.', '2005-04-21 15:01:26.000000', NULL, 1),
(1311192, 167105, 27845, '<td valign="top">Funny. I would have preferred coloured paper. 6.</td>', 'Funny. I would have preferred coloured paper. 6.', '2005-04-21 15:25:04.000000', NULL, 1),
(1311195, 168688, 27845, '<td valign="top">Great lighting. I like how the image is split in two parts. But it looks overedited: too much contrast, and the woman is out of focus, or so it seems. Might be a postprocessing matter as well. 7.</td>', 'Great lighting. I like how the image is split in two parts. But it looks overedited: too much contrast, and the woman is out of focus, or so it seems. Might be a postprocessing matter as well. 7.', '2005-04-21 15:28:39.000000', NULL, 1),
