(1311220, 168520, 33435, '<td valign="top">This could have been much better.  If you wanted the rock as the subject, you could have angled it better, or moved the rock into an area much less distractive</td>', 'This could have been much better.  If you wanted the rock as the subject, you could have angled it better, or moved the rock into an area much less distractive', '2005-04-21 15:45:24.000000', NULL, 1),
(1311222, 166682, 36324, '<td valign="top">Nice picture of the tiger, my low vote is for category...there are rocks, but not the theme of the picture...</td>', 'Nice picture of the tiger, my low vote is for category...there are rocks, but not the theme of the picture...', '2005-04-21 15:49:22.000000', NULL, 1),
