(1314294, 167448, 30982, '<td valign="top">Clever idea!</td>', 'Clever idea!', '2005-04-22 21:35:43.000000', NULL, 1),
(1314320, 167191, 30982, '<td valign="top">OK, where''d you get so many pairs of scissors?  Nice visual design!</td>', 'OK, where''d you get so many pairs of scissors?  Nice visual design!', '2005-04-22 21:50:22.000000', NULL, 1),
(1314329, 168299, 35645, '<td valign="top">I like the concept. The trees in the center are too busy and distract/detract from the city skyline. The left side of the arch is cut off, which gives an out of balance feel to the photo which is emphasized by the tilted horizon. On the plus side, the focus and DOF is good, and the lighting on the stones is good.</td>', 'I like the concept. The trees in the center are too busy and distract/detract from the city skyline. The left side of the arch is cut off, which gives an out of balance feel to the photo which is emphasized by the tilted horizon. On the plus side, the focus and DOF is good, and the lighting on the stones is good.', '2005-04-22 21:53:03.000000', NULL, 1),
(1314334, 167627, 35645, '<td valign="top">Try pulling back from the subject just a little; the crop is too tight and causes the composition to feel static and a little claustrophobic - there is no ''frame'' to support the rock.</td>', 'Try pulling back from the subject just a little; the crop is too tight and causes the composition to feel static and a little claustrophobic - there is no ''frame'' to support the rock.', '2005-04-22 21:56:39.000000', NULL, 1),
(1314339, 167200, 35645, '<td valign="top">Good idea. Nice colors. Out of focus. Also, a slightly tighter crop would pull  the focus more to the center shrubbery; as it stand now, it looks like the bushes on either end are accidentally chopped off which gives the photo an unfinished feel.</td>', 'Good idea. Nice colors. Out of focus. Also, a slightly tighter crop would pull  the focus more to the center shrubbery; as it stand now, it looks like the bushes on either end are accidentally chopped off which gives the photo an unfinished feel.', '2005-04-22 21:58:42.000000', NULL, 1),
(1314341, 168281, 35645, '<td valign="top">The foreground flowers, while they add depth to the composition, are distracting because of their brightness. Perhaps this shot from another angle would work better?</td>', 'The foreground flowers, while they add depth to the composition, are distracting because of their brightness. Perhaps this shot from another angle would work better?', '2005-04-22 22:00:22.000000', NULL, 1),
(1314342, 168685, 35645, '<td valign="top">I think there may be a decent (or even good) photo in there, but it''s too dark and too small to see.</td>', 'I think there may be a decent (or even good) photo in there, but it''s too dark and too small to see.', '2005-04-22 22:01:42.000000', NULL, 1),
(1314347, 167302, 35645, '<td valign="top">The crane is nice. I like the idea, but the two-tone background is distracting, especially since you can see that the green (grey?) material is out of focus and is reflecting the light in an unhelpful manner. Try a solid, non-reflective background, with the vertical part of the background angled slightly.</td>', 'The crane is nice. I like the idea, but the two-tone background is distracting, especially since you can see that the green (grey?) material is out of focus and is reflecting the light in an unhelpful manner. Try a solid, non-reflective background, with the vertical part of the background angled slightly.', '2005-04-22 22:06:39.000000', NULL, 1),
(1314349, 168684, 30982, '<td valign="top">Love the title.</td>', 'Love the title.', '2005-04-22 22:07:18.000000', NULL, 1),
(1314379, 167880, 30982, '<td valign="top">Nicely composed, though I''m guessing most will not see a connection to the challenge.  The whay the tracks line up remind me of scissors, though.</td>', 'Nicely composed, though I''m guessing most will not see a connection to the challenge.  The whay the tracks line up remind me of scissors, though.', '2005-04-22 22:25:23.000000', NULL, 1),
(1314383, 168447, 30982, '<td valign="top">One of my top three of the challenge, from the thumbnail through complete voting.</td>', 'One of my top three of the challenge, from the thumbnail through complete voting.', '2005-04-22 22:30:19.000000', NULL, 1),
