(1315625, 167155, 4793, '<td valign="top">Beautiful colors nice composition, what is the green stone? very nice shot</td>', 'Beautiful colors nice composition, what is the green stone? very nice shot', '2005-04-23 16:15:06.000000', NULL, 1),
(1315639, 168673, 19978, '<td valign="top">Seems to me an uninteresting shot. Nothing captures my eye and makes me wonder or say "wow." Shooting an interesting shot with rocks as the subject is tough, I know. 5.</td>', 'Seems to me an uninteresting shot. Nothing captures my eye and makes me wonder or say "wow." Shooting an interesting shot with rocks as the subject is tough, I know. 5.', '2005-04-23 16:26:39.000000', NULL, 1),
(1315642, 168472, 19978, '<td valign="top">Possibly, but the beauty does not emerge from this photo. Shooting an interested shot of a rock is a tough challenge, I admit. Perhaps relying more in dramatic lighting and contrast between light and shadow? This shot contains no immediate draw for the eye, and doesn''t have any "wow" factor. 5.</td>', 'Possibly, but the beauty does not emerge from this photo. Shooting an interested shot of a rock is a tough challenge, I admit. Perhaps relying more in dramatic lighting and contrast between light and shadow? This shot contains no immediate draw for the eye, and doesn''t have any "wow" factor. 5.', '2005-04-23 16:28:02.000000', NULL, 1),
(1315643, 167200, 36634, '<td valign="top">I Like the grey and green shading</td>', 'I Like the grey and green shading', '2005-04-23 16:29:24.000000', NULL, 1),
