(1329096, 167288, 4517, '<td valign="top">Now that`s different, well spotted.</td>', 'Now that`s different, well spotted.', '2005-04-26 17:06:38.000000', NULL, 1),
(1329098, 168399, 4517, '<td valign="top">Quite poor image quality but that`s probaly down to your camera.</td>', 'Quite poor image quality but that`s probaly down to your camera.', '2005-04-26 17:07:53.000000', NULL, 1),
(1329099, 167612, 25095, '<td valign="top">wonderful image, you kept the ragged rocks sharp while giving the water a nice soft feel.  Great use of lighting (sunrise?) and best of all you stayed away from the typical submission idea.  You are one of the few in this challenge that shows yourself as a professional (or at least very advanced hobbiest).  Good job.</td>', 'wonderful image, you kept the ragged rocks sharp while giving the water a nice soft feel.  Great use of lighting (sunrise?) and best of all you stayed away from the typical submission idea.  You are one of the few in this challenge that shows yourself as a professional (or at least very advanced hobbiest).  Good job.', '2005-04-26 17:08:22.000000', NULL, 1),
(1329102, 168341, 4517, '<td valign="top">Good colour and sharpness.</td>', 'Good colour and sharpness.', '2005-04-26 17:09:04.000000', NULL, 1),
(1329103, 168116, 4517, '<td valign="top">lol, funny shot, looks a little over sharpened.</td>', 'lol, funny shot, looks a little over sharpened.', '2005-04-26 17:09:49.000000', NULL, 1),
