(1329111, 167207, 4517, '<td valign="top">:) Good idea</td>', ':) Good idea', '2005-04-26 17:13:25.000000', NULL, 1),
(1329112, 166358, 26679, '<td valign="top">The colour here are fantastic, for me thought the link to theme of rock, paper, scissors is a bit of a stretch. However as a straight photograph this is excellent.</td>', 'The colour here are fantastic, for me thought the link to theme of rock, paper, scissors is a bit of a stretch. However as a straight photograph this is excellent.', '2005-04-26 17:13:26.000000', NULL, 1),
