(1329154, 168417, 4517, '<td valign="top">Nice family snap, but technically could be better.</td>', 'Nice family snap, but technically could be better.', '2005-04-26 17:31:48.000000', NULL, 1),
(1329162, 167451, 4517, '<td valign="top">Good photogenic scene but would like to see the waterfall more rather than the forground rocks. It would still fit the challenge fine without them.</td>', 'Good photogenic scene but would like to see the waterfall more rather than the forground rocks. It would still fit the challenge fine without them.', '2005-04-26 17:35:05.000000', NULL, 1),
