(1329493, 166482, 30861, '<td valign="top">The ambiguity of scale here is fascinating. Nice image, tautly composed.</td>', 'The ambiguity of scale here is fascinating. Nice image, tautly composed.', '2005-04-26 19:52:11.000000', NULL, 1),
(1329497, 167378, 30861, '<td valign="top">This deceptively simple composition if worth a second, and a third, look. Bumping up. My first reactionw as "not sharp", but now the softness seems to work well for the subject.</td>', 'This deceptively simple composition if worth a second, and a third, look. Bumping up. My first reactionw as "not sharp", but now the softness seems to work well for the subject.', '2005-04-26 19:53:16.000000', NULL, 1),
(1329508, 168125, 30861, '<td valign="top">In many ways a very powerful image, but I have several nits. The cliffs themselves don''t seem to be rendered as wella s they might be, and even though the horizon is almost perfectly level the ooveralls ense is that it''s leaning slightly to the right, like it needs half a degree of ccw rotation to balance it. Finally, the very wide one-two punch of border is really hurting you here, it''s greatly at odds witht he delicacy of the photo details, and overpowers them badly.</td>', 'In many ways a very powerful image, but I have several nits. The cliffs themselves don''t seem to be rendered as wella s they might be, and even though the horizon is almost perfectly level the ooveralls ense is that it''s leaning slightly to the right, like it needs half a degree of ccw rotation to balance it. Finally, the very wide one-two punch of border is really hurting you here, it''s greatly at odds witht he delicacy of the photo details, and overpowers them badly.', '2005-04-26 19:56:07.000000', NULL, 1),
(1329509, 168697, 30861, '<td valign="top">Intriguing composition. I might prefer a true vertical for the dominant N/S element.</td>', 'Intriguing composition. I might prefer a true vertical for the dominant N/S element.', '2005-04-26 19:56:59.000000', NULL, 1),
